                    return true;  // At least one scanner failed
                }
            }
            return false;
        })->count();

        $rate = new FailureRate($total, $degraded, (int) $config['min_samples']);

        if ($rate->percent() > (int) $config['fail_percent']) {
            return $result->failed("{$degraded} of {$rate->total} runs had a scanner that did not complete.");
        }
        return $result->ok();
    }
